---@class UIFeelingFavorabilityRoleNode
local UIFeelingFavorabilityRoleNode = Class("UIFeelingFavorabilityRoleNode")
function UIFeelingFavorabilityRoleNode:__init() 
    self._curCatId = nil
    self._roleCb = nil
    self._changeNameCb = nil
    self._changeFormCb = nil
end

function UIFeelingFavorabilityRoleNode:__delete()
    self._curCatId = nil
    self._index = nil
    self._clickCb = nil
end

function UIFeelingFavorabilityRoleNode:Awake()
    SetButtonAction(self.ImgRoleBg, Bind(self, self.OnSelectCat))
    SetButtonAction(self.BtnNamd, Bind(self, self.OnChangeName))
    SetButtonAction(self.BtnFigure, Bind(self, self.OnChangeForm))
    SetButtonAction(self.BtnSet, Bind(self, self.OnSetting))
end

function UIFeelingFavorabilityRoleNode:Start()
    CfUtils.FillText(self.TextCf1, localize("变更称呼"))
    CfUtils.FillText(self.TextCf2, localize("变更形象"))

end

function UIFeelingFavorabilityRoleNode:Refresh(id, roleCb, changeNameCb, changeFormCb)
    self._curCatId = id
    self._roleCb = roleCb
    self._changeNameCb = changeNameCb
    self._changeFormCb = changeFormCb
    
    local data = phoneComp:GetCatDataById(id)
    if not data then
        return
    end
    self:FillRole(data)
    KTool.SetActive(self.Root, true)
end

function UIFeelingFavorabilityRoleNode:FillRole(data)
    local skinCardId = PhoneUtils.GetRoleCurCardSkinId(data.catId)
    CfUtils.FillImage(self.ImgRoleIcon, CardConfMgr:GetInstance():GetCardDefaultBodyIconPath(skinCardId))

    local isUnlock = PhoneUtils.IsUnlockCatById(data.catId)
    KTool.SetActive(self.Group1, isUnlock)
    KTool.SetActive(self.Group2, not isUnlock)
    KTool.SetActive(self.UnlockLockGroup, isUnlock)
    KTool.SetActive(self.LockGroup, not isUnlock)

    --如果解锁
    if isUnlock then
        --CfUtils.SetColor(self.TxtName, Color(64/255, 64/255, 64/255, 1))
        CfUtils.SetUISwitchText(self.TxtName, 1)
        CfUtils.FillText(self.Text, PhoneUtils.GetCatCurSign(data.catId))
        local level, exp = PhoneUtils.GetCatFavorabilityLevelAndCurExp(data.catId)
        CfUtils.FillText(self.HeartText, level)
        self.sliderBg.value = checkNumber(exp) / PhoneUtils.GetLikabilityLevelUpAllExp(level)
        CfUtils.FillText(self.TxtCurrent, exp.."/"..PhoneUtils.GetLikabilityLevelUpAllExp(level))
    else
        --CfUtils.SetColor(self.TxtName, Color(176/255, 176/255, 176/255, 1))
        CfUtils.SetUISwitchText(self.TxtName, 2)
    end
    CfUtils.FillText(self.TxtName, PhoneUtils.GetRoleCurName(data.catId))

    local redPointGo = GameUtils.GetRedPointGo(self.Root)
    if PhoneUtils.IsCatHasNotDrawReward(data.catId) then
        if redPointGo then
            --redPointGo.transform:GetComponent(typeof(RectTransform)).anchoredPosition = Vector2(-250, -24)
            KTool.SetActive(redPointGo, true)
        end
    else
        KTool.SetActive(redPointGo, false)
    end

    self:RefreshUnSelect()
end

--刷新选中
function UIFeelingFavorabilityRoleNode:RefreshSelect()
    KTool.SetActive(self.PopupBtnGroup, true)
    CfUtils.FillImage(self.BtnSet, "UIAtlas/Feeling/Favorability/feeling_btn_setup_2.png")
end

--刷新未选中
function UIFeelingFavorabilityRoleNode:RefreshUnSelect()
    KTool.SetActive(self.PopupBtnGroup, false)
    CfUtils.FillImage(self.BtnSet, "UIAtlas/Feeling/Favorability/feeling_btn_setup_2.png")
end

--设置
function UIFeelingFavorabilityRoleNode:OnSetting()
    if self._roleCb then
        self._roleCb()
    end
end

--点击角色
function UIFeelingFavorabilityRoleNode:OnSelectCat()
    local isUnlock = PhoneUtils.IsUnlockCatById(self._curCatId)
    if isUnlock then
        UIModule.OpenDialog({ id = Constants.UITypeIds.UIFeelingFavorabilityRewardDialog, parameters = {catId = self._curCatId}}, {
        })
    else
        GameUtils.Toast(localize("该名片未解锁"))
    end
end

--修改名字
function UIFeelingFavorabilityRoleNode:OnChangeName()
    CfUtils.SetTopCommonActive(false, false)
    local curName, cardName = PhoneUtils.GetRoleCurName(self._curCatId)
    GameUtils.FourConfirm(localize("变更称呼"), curName, cardName, nil, function(value)
        local length = utf8.len(value)
        local confirmSucceed = length <= MAX_NAME_LENGTH
        if confirmSucceed then
            phoneComp:PhoneSaveNameReq(self._curCatId, value, function()
                CfUtils.FillText(self.TxtName, value)
            end)
        else
            GameUtils.Toast(localize("昵称最长7个字"))
        end
        CfUtils.SetTopCommonActive(true, false)
    end, function()
        CfUtils.SetTopCommonActive(true, false)
    end)
end

--修改形象
function UIFeelingFavorabilityRoleNode:OnChangeForm()
    UIModule.OpenDialog({ id = Constants.UITypeIds.UIFeelingFavorabilityFigureDialog, parameters = {catId = self._curCatId}}, {
        {id = Constants.UITypeIds.UIFeelingFavorabilityDialog}
    })
end

function UIFeelingFavorabilityRoleNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIFeelingFavorabilityRoleNode
